#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_push_full_stack_double_array_fails(void) {
    /* Path 3: ptr != NULL, stack is full (ptr->top == capacity-1),
     * double_array returns NULL (result == NULL), function returns -1.
     * We need to create a stack, fill it to capacity, then cause double_array to fail.
     * create_stack makes 2 allocations (struct + array).
     * double_array will attempt a malloc for the new array.
     * We need the first 2 allocations (setup) to succeed, then the 3rd (inside double_array) to fail.
     */
    DArrayStack *stack = NULL;
    int capacity = 5;
    int data = 42;
    int push_result;

    /* Create a valid stack */
    stack = create_stack(capacity);
    TEST_ASSERT_NOT_NULL(stack);

    /* Fill the stack to capacity */
    for (int i = 0; i < capacity; i++) {
        push_result = push(stack, i * 10);
        TEST_ASSERT_EQUAL_INT(i, push_result); /* top index should be i */
    }
    /* Now stack is full: top == capacity-1 */

    /* Cause the next malloc (inside double_array) to fail */
    malloc_fail_after(2); /* First 2 allocations succeeded (create_stack), fail the 3rd */

    /* Attempt to push another element - should trigger double_array which will fail */
    push_result = push(stack, data);
    TEST_ASSERT_EQUAL_INT(-1, push_result); /* Expected return -1 per path */

    /* Cleanup */
    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_push_full_stack_double_array_fails);
    return UNITY_END();
}

